    Widget w;
    if (filled) {
      final g = _filled[name]!;
      w = Icon(size <= 16 ? g[0] : size <= 20 ? g[1] : g[2], size: size, color: ink);
    } else {
      w = SizedBox.square(dimension: size, child: CustomPaint(painter: _Km1BPainter(name, size, ink,
          // ハイコントラストと強い背景の上（color を渡したとき）は面を描かない / no tint in high contrast or with an explicit state color
          hc || color != null ? null : [c.iconTintStart, c.iconTintEnd])));
    }
    return semanticLabel == null ? ExcludeSemantics(child: w) : Semantics(label: semanticLabel, image: true, child: ExcludeSemantics(child: w));
