class _Km1BPainter extends CustomPainter {
  _Km1BPainter(this.name, this.px, this.ink, this.tint);
  final Km1BIconName name;
  final double px;
  final Color ink;
  final List<Color>? tint;

  @override
  void paint(Canvas canvas, Size size) {
    canvas.scale(size.width / 20);
    final k = px <= 16 ? 0 : px <= 20 ? 1 : 2;
    switch (name) {
      case Km1BIconName.timetable: {
        if (k == 0) {
          if (tint != null) {
            final t = Path()..fillType = PathFillType.nonZero;
            t.moveTo(4, 4.25);
            t.lineTo(16, 4.25);
            t.cubicTo(16.69, 4.25, 17.25, 4.81, 17.25, 5.5);
            t.lineTo(17.25, 15.75);
            t.cubicTo(17.25, 16.44, 16.69, 17, 16, 17);
            t.lineTo(4, 17);
            t.cubicTo(3.31, 17, 2.75, 16.44, 2.75, 15.75);
            t.lineTo(2.75, 5.5);
            t.cubicTo(2.75, 4.81, 3.31, 4.25, 4, 4.25);
            t.close();
            canvas.drawPath(t, Paint()..shader = LinearGradient(begin: Alignment.topCenter, end: Alignment.bottomCenter, colors: tint!).createShader(const Rect.fromLTRB(0, 4, 20, 17)));
          }
          final s = Path()..fillType = PathFillType.nonZero;
          s.moveTo(12.69, 2.75);
          s.quadraticBezierTo(12.69, 1.94, 13.5, 1.94);
          s.quadraticBezierTo(14.31, 1.94, 14.31, 2.75);
          s.lineTo(14.31, 3.44);
          s.lineTo(16, 3.44);
          s.quadraticBezierTo(18.06, 3.44, 18.06, 5.5);
          s.lineTo(18.06, 15.75);
          s.quadraticBezierTo(18.06, 17.81, 16, 17.81);
          s.lineTo(4, 17.81);
          s.quadraticBezierTo(3.15, 17.81, 2.54, 17.21);
          s.quadraticBezierTo(1.94, 16.6, 1.94, 15.75);
          s.lineTo(1.94, 5.5);
